-- Connected course publishing, learner runtime, progress, and grading.
create table if not exists public.course_publications (
  id uuid primary key default gen_random_uuid(), course_id uuid not null unique references public.courses(id) on delete restrict,
  created_by uuid not null references public.profiles(id) on delete restrict, current_version integer not null default 0 check (current_version >= 0),
  status text not null default 'draft' check (status in ('draft','published','unpublished','archived')),
  display_mode text not null default 'full_course' check (display_mode in ('full_course','embedded_module')),
  theme_preset text not null default 'ednotebook-default', grading_mode text not null default 'auto' check (grading_mode in ('auto','manual','mixed')),
  grade_item_id uuid references public.grade_items(id) on delete set null, draft_manifest jsonb not null default '{}'::jsonb,
  published_at timestamptz, unpublished_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.course_publication_versions (
  publication_id uuid not null references public.course_publications(id) on delete cascade,
  version_number integer not null check (version_number > 0), manifest jsonb not null, change_summary text not null default '',
  published_by uuid not null references public.profiles(id) on delete restrict, published_at timestamptz not null default now(),
  primary key (publication_id, version_number)
);
create table if not exists public.course_lesson_progress (
  id uuid primary key default gen_random_uuid(), publication_id uuid not null references public.course_publications(id) on delete cascade,
  course_id uuid not null references public.courses(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade,
  version_number integer not null default 1, path_id text not null, lesson_id text not null, section_index integer not null default 0 check (section_index >= 0),
  phase text not null default 'lesson' check (phase in ('lesson','scenario','knowledge','quiz','assignment','complete')),
  status text not null default 'in_progress' check (status in ('not_started','in_progress','completed')),
  interaction_state jsonb not null default '{}'::jsonb, auto_score numeric(5,2), opened_at timestamptz not null default now(), completed_at timestamptz,
  updated_at timestamptz not null default now(), unique (publication_id, user_id, path_id, lesson_id)
);
create table if not exists public.course_progress (
  id uuid primary key default gen_random_uuid(), publication_id uuid not null references public.course_publications(id) on delete cascade,
  course_id uuid not null references public.courses(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade,
  version_number integer not null default 1, current_path_id text, current_lesson_id text, current_section_index integer not null default 0 check (current_section_index >= 0),
  status text not null default 'in_progress' check (status in ('not_started','in_progress','completed')), completed_lessons integer not null default 0 check (completed_lessons >= 0),
  total_lessons integer not null default 0 check (total_lessons >= 0), completion_percent numeric(5,2) not null default 0, auto_score numeric(5,2), final_score numeric(5,2),
  grade_status text not null default 'in_progress' check (grade_status in ('in_progress','auto_graded','awaiting_grading','graded')), feedback text,
  completed_at timestamptz, last_opened_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (publication_id, user_id)
);
create index if not exists course_publications_course_idx on public.course_publications(course_id);
create index if not exists course_publication_versions_pub_idx on public.course_publication_versions(publication_id, version_number desc);
create index if not exists course_lesson_progress_user_idx on public.course_lesson_progress(user_id, updated_at desc);
create index if not exists course_lesson_progress_course_idx on public.course_lesson_progress(course_id, status);
create index if not exists course_progress_user_idx on public.course_progress(user_id, updated_at desc);
create index if not exists course_progress_course_idx on public.course_progress(course_id, status);
alter table public.course_publications enable row level security; alter table public.course_publication_versions enable row level security;
alter table public.course_lesson_progress enable row level security; alter table public.course_progress enable row level security;
revoke all on public.course_publications from anon; revoke all on public.course_publication_versions from anon;
revoke all on public.course_lesson_progress from anon; revoke all on public.course_progress from anon;
grant select, insert, update on public.course_publications to authenticated; grant select, insert on public.course_publication_versions to authenticated;
grant select, insert, update on public.course_lesson_progress to authenticated; grant select, insert, update on public.course_progress to authenticated;
create policy course_publications_select on public.course_publications for select to authenticated using (private.can_manage_course(course_id) or (status = 'published' and private.can_access_course(course_id)));
create policy course_publications_insert on public.course_publications for insert to authenticated with check (created_by = auth.uid() and private.can_manage_course(course_id));
create policy course_publications_update on public.course_publications for update to authenticated using (private.can_manage_course(course_id)) with check (private.can_manage_course(course_id));
create policy course_publication_versions_select on public.course_publication_versions for select to authenticated using (exists (select 1 from public.course_publications p where p.id = publication_id and (private.can_manage_course(p.course_id) or (p.status = 'published' and private.can_access_course(p.course_id)))));
create policy course_publication_versions_insert on public.course_publication_versions for insert to authenticated with check (published_by = auth.uid() and exists (select 1 from public.course_publications p where p.id = publication_id and private.can_manage_course(p.course_id)));
create policy course_lesson_progress_select on public.course_lesson_progress for select to authenticated using (user_id = auth.uid() or private.can_manage_course(course_id));
create policy course_lesson_progress_insert on public.course_lesson_progress for insert to authenticated with check (user_id = auth.uid() and private.can_access_course(course_id));
create policy course_lesson_progress_update on public.course_lesson_progress for update to authenticated using (user_id = auth.uid() or private.can_manage_course(course_id)) with check (user_id = auth.uid() or private.can_manage_course(course_id));
create policy course_progress_select on public.course_progress for select to authenticated using (user_id = auth.uid() or private.can_manage_course(course_id));
create policy course_progress_insert on public.course_progress for insert to authenticated with check (user_id = auth.uid() and private.can_access_course(course_id));
create policy course_progress_update on public.course_progress for update to authenticated using (user_id = auth.uid() or private.can_manage_course(course_id)) with check (user_id = auth.uid() or private.can_manage_course(course_id));
create or replace function private.course_runtime_manifest_valid(p_manifest jsonb) returns boolean language sql immutable set search_path = public, pg_temp as $$ select coalesce(p_manifest->>'format','') = 'EdNotebookCourse/1.0' and jsonb_typeof(p_manifest->'course') = 'object' and length(trim(coalesce(p_manifest->'course'->>'title',''))) > 0 and jsonb_typeof(p_manifest->'paths') = 'array' and jsonb_array_length(p_manifest->'paths') > 0; $$;
create or replace function public.save_course_package_draft(p_course_id uuid,p_manifest jsonb,p_display_mode text default 'full_course',p_theme_preset text default 'ednotebook-default',p_grading_mode text default 'auto') returns public.course_publications language plpgsql security definer set search_path = public, private, pg_temp as $$ declare v_row public.course_publications; begin if auth.uid() is null or not private.can_manage_course(p_course_id) then raise exception 'course access denied'; end if; if not private.course_runtime_manifest_valid(p_manifest) then raise exception 'invalid EdNotebookCourse/1.0 package'; end if; insert into public.course_publications(course_id,created_by,draft_manifest,display_mode,theme_preset,grading_mode) values(p_course_id,auth.uid(),p_manifest,p_display_mode,p_theme_preset,case when p_grading_mode in ('auto','manual','mixed') then p_grading_mode else 'auto' end) on conflict(course_id) do update set draft_manifest=excluded.draft_manifest,display_mode=excluded.display_mode,theme_preset=excluded.theme_preset,grading_mode=excluded.grading_mode,updated_at=now() returning * into v_row; return v_row; end; $$;
create or replace function public.publish_course_package(p_course_id uuid,p_manifest jsonb,p_display_mode text default 'full_course',p_theme_preset text default 'ednotebook-default',p_grading_mode text default 'auto',p_change_summary text default '') returns public.course_publications language plpgsql security definer set search_path = public, private, pg_temp as $$ declare v_publication public.course_publications; v_course public.courses; v_profile public.profiles; v_institution_name text; v_next_version integer; v_grade_item uuid; v_grade_mode text; begin if auth.uid() is null or not private.can_manage_course(p_course_id) then raise exception 'course access denied'; end if; if not private.course_runtime_manifest_valid(p_manifest) then raise exception 'invalid EdNotebookCourse/1.0 package'; end if; select * into v_course from public.courses where id=p_course_id for update; if not found then raise exception 'course not found'; end if; select * into v_profile from public.profiles where id=auth.uid(); select name into v_institution_name from public.institutions where id=v_course.institution_id; v_institution_name:=coalesce(v_institution_name,'Independent course'); v_grade_mode:=case when p_grading_mode in ('auto','manual','mixed') then p_grading_mode else 'auto' end; insert into public.course_publications(course_id,created_by,draft_manifest,display_mode,theme_preset,grading_mode) values(p_course_id,auth.uid(),p_manifest,p_display_mode,p_theme_preset,v_grade_mode) on conflict(course_id) do update set draft_manifest=excluded.draft_manifest,display_mode=excluded.display_mode,theme_preset=excluded.theme_preset,grading_mode=excluded.grading_mode,updated_at=now() returning * into v_publication; v_next_version:=v_publication.current_version+1; insert into public.course_publication_versions(publication_id,version_number,manifest,change_summary,published_by) values(v_publication.id,v_next_version,p_manifest,left(coalesce(p_change_summary,''),1000),auth.uid()); if v_publication.grade_item_id is null then insert into public.grade_items(course_id,title,max_points,publish_state,due_at) values(p_course_id,coalesce(nullif(p_manifest->'grading'->>'title',''),'Course completion · '||v_course.title),coalesce(nullif(p_manifest->'grading'->>'maxPoints','')::numeric,100),'published',nullif(p_manifest->'grading'->>'dueAt','')::timestamptz) returning id into v_grade_item; else v_grade_item:=v_publication.grade_item_id; update public.grade_items set title=coalesce(nullif(p_manifest->'grading'->>'title',''),title),max_points=coalesce(nullif(p_manifest->'grading'->>'maxPoints','')::numeric,max_points),due_at=nullif(p_manifest->'grading'->>'dueAt','')::timestamptz,publish_state='published',updated_at=now() where id=v_grade_item; end if; update public.course_publications set current_version=v_next_version,status='published',grade_item_id=v_grade_item,published_at=coalesce(published_at,now()),unpublished_at=null,updated_at=now() where id=v_publication.id returning * into v_publication; update public.courses set status='published',updated_at=now() where id=p_course_id; insert into public.published_course_directory(course_id,institution_id,professor_id,institution_name,professor_display_name,course_code,title,subject,term,schedule,summary,enrollment_open,is_listed,published_at,education_division,educator_verification_status) values(p_course_id,v_course.institution_id,v_course.owner_id,v_institution_name,coalesce(nullif(v_profile.full_name,''),split_part(coalesce(v_profile.email,'Professor'),'@',1)),coalesce(nullif(v_course.course_code,''),'COURSE'),v_course.title,v_course.subject,v_course.teaching_window,null,coalesce(nullif(p_manifest->'course'->>'description',''),v_course.audience),true,true,now(),v_course.education_division,coalesce((select status from public.educator_verification_requests where user_id=v_course.owner_id),'unverified')) on conflict(course_id) do update set institution_id=excluded.institution_id,professor_id=excluded.professor_id,institution_name=excluded.institution_name,professor_display_name=excluded.professor_display_name,course_code=excluded.course_code,title=excluded.title,subject=excluded.subject,term=excluded.term,summary=excluded.summary,enrollment_open=true,is_listed=true,published_at=coalesce(public.published_course_directory.published_at,now()),education_division=excluded.education_division,educator_verification_status=excluded.educator_verification_status,updated_at=now(); return v_publication; end; $$;
create or replace function public.set_course_publication_state(p_publication_id uuid,p_status text) returns public.course_publications language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_row public.course_publications; begin select * into v_row from public.course_publications where id=p_publication_id; if not found or auth.uid() is null or not private.can_manage_course(v_row.course_id) then raise exception 'course access denied'; end if; if p_status not in ('published','unpublished','archived') then raise exception 'invalid publication state'; end if; update public.course_publications set status=p_status,unpublished_at=case when p_status='published' then null else now() end,updated_at=now() where id=p_publication_id returning * into v_row; update public.courses set status=case when p_status='published' then 'published' else 'draft' end,updated_at=now() where id=v_row.course_id; update public.published_course_directory set is_listed=(p_status='published'),enrollment_open=(p_status='published'),updated_at=now() where course_id=v_row.course_id; return v_row; end; $$;
create or replace function public.save_course_lesson_progress(p_publication_id uuid,p_path_id text,p_lesson_id text,p_section_index integer,p_phase text,p_interaction_state jsonb default '{}'::jsonb,p_complete boolean default false) returns public.course_progress language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_pub public.course_publications; v_manifest jsonb; v_node jsonb; v_check jsonb; v_total_questions integer:=0; v_correct integer:=0; v_lesson_score numeric(5,2):=null; v_total_lessons integer:=0; v_completed integer:=0; v_auto_score numeric(5,2):=null; v_course_status text:='in_progress'; v_grade_status text:='in_progress'; v_progress public.course_progress; v_max_points numeric:=100; begin if auth.uid() is null then raise exception 'authentication required'; end if; select * into v_pub from public.course_publications where id=p_publication_id and status='published'; if not found or not private.can_access_course(v_pub.course_id) then raise exception 'course access denied'; end if; select manifest into v_manifest from public.course_publication_versions where publication_id=v_pub.id and version_number=v_pub.current_version; select node into v_node from jsonb_array_elements(v_manifest->'paths') path,jsonb_array_elements(path->'nodes') node where path->>'id'=p_path_id and node->>'id'=p_lesson_id limit 1; if v_node is null then raise exception 'lesson not found'; end if; if p_complete then for v_check in select value from jsonb_array_elements(coalesce(v_node->'knowledgeChecks','[]'::jsonb)) loop v_total_questions:=v_total_questions+1; if coalesce(p_interaction_state->'knowledgeAnswers'->>(v_check->>'id'),'')=coalesce(v_check->>'correctAnswer','') then v_correct:=v_correct+1; end if; end loop; for v_check in select value from jsonb_array_elements(coalesce(v_node->'endQuiz','[]'::jsonb)) loop v_total_questions:=v_total_questions+1; if coalesce(p_interaction_state->'quizAnswers'->>(v_check->>'id'),'')=coalesce(v_check->>'correctAnswer','') then v_correct:=v_correct+1; end if; end loop; v_lesson_score:=case when v_total_questions=0 then 100 else round((v_correct::numeric/v_total_questions::numeric)*100,2) end; end if; insert into public.course_lesson_progress(publication_id,course_id,user_id,version_number,path_id,lesson_id,section_index,phase,status,interaction_state,auto_score,completed_at,updated_at) values(v_pub.id,v_pub.course_id,auth.uid(),v_pub.current_version,p_path_id,p_lesson_id,greatest(coalesce(p_section_index,0),0),case when p_phase in ('lesson','scenario','knowledge','quiz','assignment','complete') then p_phase else 'lesson' end,case when p_complete then 'completed' else 'in_progress' end,coalesce(p_interaction_state,'{}'::jsonb),v_lesson_score,case when p_complete then now() else null end,now()) on conflict(publication_id,user_id,path_id,lesson_id) do update set version_number=excluded.version_number,section_index=excluded.section_index,phase=excluded.phase,status=case when public.course_lesson_progress.status='completed' then 'completed' else excluded.status end,interaction_state=excluded.interaction_state,auto_score=coalesce(excluded.auto_score,public.course_lesson_progress.auto_score),completed_at=coalesce(public.course_lesson_progress.completed_at,excluded.completed_at),updated_at=now(); select coalesce(sum(jsonb_array_length(path->'nodes')),0)::integer into v_total_lessons from jsonb_array_elements(v_manifest->'paths') path; select count(*)::integer,round(avg(auto_score),2) into v_completed,v_auto_score from public.course_lesson_progress where publication_id=v_pub.id and user_id=auth.uid() and status='completed'; if v_total_lessons>0 and v_completed>=v_total_lessons then v_course_status:='completed'; v_grade_status:=case when v_pub.grading_mode='auto' then 'auto_graded' else 'awaiting_grading' end; end if; insert into public.course_progress(publication_id,course_id,user_id,version_number,current_path_id,current_lesson_id,current_section_index,status,completed_lessons,total_lessons,completion_percent,auto_score,final_score,grade_status,completed_at,last_opened_at,updated_at) values(v_pub.id,v_pub.course_id,auth.uid(),v_pub.current_version,p_path_id,p_lesson_id,greatest(coalesce(p_section_index,0),0),v_course_status,v_completed,v_total_lessons,case when v_total_lessons=0 then 0 else round((v_completed::numeric/v_total_lessons::numeric)*100,2) end,v_auto_score,case when v_grade_status='auto_graded' then v_auto_score else null end,v_grade_status,case when v_course_status='completed' then now() else null end,now(),now()) on conflict(publication_id,user_id) do update set version_number=excluded.version_number,current_path_id=excluded.current_path_id,current_lesson_id=excluded.current_lesson_id,current_section_index=excluded.current_section_index,status=excluded.status,completed_lessons=excluded.completed_lessons,total_lessons=excluded.total_lessons,completion_percent=excluded.completion_percent,auto_score=excluded.auto_score,final_score=case when public.course_progress.grade_status='graded' then public.course_progress.final_score else excluded.final_score end,grade_status=case when public.course_progress.grade_status='graded' then 'graded' else excluded.grade_status end,completed_at=coalesce(public.course_progress.completed_at,excluded.completed_at),last_opened_at=now(),updated_at=now() returning * into v_progress; if v_course_status='completed' and v_pub.grade_item_id is not null then select max_points into v_max_points from public.grade_items where id=v_pub.grade_item_id; insert into public.student_grades(course_id,grade_item_id,student_id,score,status,published_at,finalized_at) values(v_pub.course_id,v_pub.grade_item_id,auth.uid(),case when v_pub.grading_mode='auto' then round(coalesce(v_auto_score,100)*v_max_points/100,2) else null end,case when v_pub.grading_mode='auto' then 'finalized' else 'pending' end,case when v_pub.grading_mode='auto' then now() else null end,case when v_pub.grading_mode='auto' then now() else null end) on conflict(grade_item_id,student_id) do update set score=excluded.score,status=excluded.status,published_at=excluded.published_at,finalized_at=excluded.finalized_at,updated_at=now(); end if; return v_progress; end; $$;
create or replace function public.grade_course_progress(p_publication_id uuid,p_student_id uuid,p_score numeric,p_feedback text default null) returns public.course_progress language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_pub public.course_publications; v_progress public.course_progress; v_max numeric:=100; begin select * into v_pub from public.course_publications where id=p_publication_id; if not found or auth.uid() is null or not private.can_manage_course(v_pub.course_id) then raise exception 'course access denied'; end if; if p_score<0 or p_score>100 then raise exception 'score must be 0 to 100'; end if; update public.course_progress set final_score=p_score,grade_status='graded',feedback=left(coalesce(p_feedback,''),5000),updated_at=now() where publication_id=p_publication_id and user_id=p_student_id returning * into v_progress; if not found then raise exception 'learner progress not found'; end if; if v_pub.grade_item_id is not null then select max_points into v_max from public.grade_items where id=v_pub.grade_item_id; insert into public.student_grades(course_id,grade_item_id,student_id,score,status,feedback,published_at,finalized_at) values(v_pub.course_id,v_pub.grade_item_id,p_student_id,round(p_score*v_max/100,2),'finalized',left(coalesce(p_feedback,''),5000),now(),now()) on conflict(grade_item_id,student_id) do update set score=excluded.score,status='finalized',feedback=excluded.feedback,published_at=now(),finalized_at=now(),updated_at=now(); end if; return v_progress; end; $$;
create or replace function public.get_course_progress_overview(p_course_id uuid) returns table(publication_id uuid,user_id uuid,student_name text,student_email text,status text,completed_lessons integer,total_lessons integer,completion_percent numeric,auto_score numeric,final_score numeric,grade_status text,feedback text,last_opened_at timestamptz,completed_at timestamptz) language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if auth.uid() is null or not private.can_manage_course(p_course_id) then raise exception 'course access denied'; end if; return query select cp.publication_id,cp.user_id,coalesce(nullif(pr.full_name,''),split_part(coalesce(pr.email,'Learner'),'@',1)),pr.email,cp.status,cp.completed_lessons,cp.total_lessons,cp.completion_percent,cp.auto_score,cp.final_score,cp.grade_status,cp.feedback,cp.last_opened_at,cp.completed_at from public.course_progress cp join public.profiles pr on pr.id=cp.user_id where cp.course_id=p_course_id order by cp.updated_at desc; end; $$;
grant execute on function public.save_course_package_draft(uuid,jsonb,text,text,text) to authenticated; grant execute on function public.publish_course_package(uuid,jsonb,text,text,text,text) to authenticated; grant execute on function public.set_course_publication_state(uuid,text) to authenticated; grant execute on function public.save_course_lesson_progress(uuid,text,text,integer,text,jsonb,boolean) to authenticated; grant execute on function public.grade_course_progress(uuid,uuid,numeric,text) to authenticated; grant execute on function public.get_course_progress_overview(uuid) to authenticated; revoke all on function private.course_runtime_manifest_valid(jsonb) from public,anon,authenticated;
create trigger course_publications_touch_updated_at before update on public.course_publications for each row execute function private.touch_updated_at();
create trigger course_lesson_progress_touch_updated_at before update on public.course_lesson_progress for each row execute function private.touch_updated_at();
create trigger course_progress_touch_updated_at before update on public.course_progress for each row execute function private.touch_updated_at();
